const fs = require("fs");

const FILE = "compendium/pt-BR/symbaroum-gmg.symbaroum-gmg.json";
const ENTRY = "Symbaroum Game Masters Guide";
const checkOnly = process.argv.includes("--check");
const source = fs.readFileSync(FILE, "utf8");
const data = JSON.parse(source);
const journals = data.entries?.[ENTRY]?.journals;
const tables = data.entries?.[ENTRY]?.tables;
const items = data.entries?.[ENTRY]?.items;
const actors = data.entries?.[ENTRY]?.actors;
if (!journals) throw new Error(`Missing '${ENTRY}' journals.`);
if (!tables) throw new Error(`Missing '${ENTRY}' tables.`);
if (!items || !actors) throw new Error(`Missing '${ENTRY}' items or actors.`);

